class MessageThrottle {
  private printed: [number, string][] = [];

  shouldPrint(timestamp: number, message: string): boolean {
    for (let i = this.printed.length - 1; i >= 0; i--) {
      const [t, m] = this.printed[i];
      if (m === message && timestamp - t < 10) return false;
    }
    this.printed.push([timestamp, message]);
    return true;
  }
}

